/**
 * @name Taint flow to pickle deserialization
 * @description Tracks data flow from remote/user input to pickle.load
 * @kind path-problem
 * @problem.severity error
 * @id py/taint-to-pickle
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization with data from $@.", source.getNode(), "user input"

/**
 * @name Taint flow to command execution
 * @description Tracks data flow from remote/user input to command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/taint-to-command-exec
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember("system").getACall() or
        call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CommandExecFlow = TaintTracking::Global<CommandExecConfig>;
import CommandExecFlow::PathGraph

from CommandExecFlow::PathNode source, CommandExecFlow::PathNode sink
where CommandExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command execution with data from $@.", source.getNode(), "user input"
